92		if request.FeedURL != nil {
93			if *request.FeedURL == "" {
94				return locale.NewLocalizedError("error.feed_url_not_empty")
95			}
96	
97			if !urllib.IsAbsoluteURL(*request.FeedURL) {
98				return locale.NewLocalizedError("error.invalid_feed_url")
99			}
100	
101			if store.AnotherFeedURLExists(userID, feedID, *request.FeedURL) {
102				return locale.NewLocalizedError("error.feed_already_exists")
103			}
104		}
105	
106		if request.SiteURL != nil {
107			if *request.SiteURL == "" {
108				return locale.NewLocalizedError("error.site_url_not_empty")
109			}
110	
111			if !urllib.IsAbsoluteURL(*request.SiteURL) {
112				return locale.NewLocalizedError("error.invalid_site_url")
113			}
114		}
115	
116		if request.Title != nil {
117			if *request.Title == "" {
118				return locale.NewLocalizedError("error.feed_title_not_empty")
119			}
120		}
121	
122		if request.CategoryID != nil {
123			categoryExists, err := store.CategoryIDExists(userID, *request.CategoryID)
124			if err != nil {
125				// See the identical rationale in ValidateFeedCreation above.
126				slog.Error("validator: unable to check if feed category exists",
127					slog.Int64("user_id", userID),
128					slog.Int64("category_id", *request.CategoryID),
