139			if !IsValidRegex(*request.BlocklistRules) {
140				return locale.NewLocalizedError("error.feed_invalid_blocklist_rule")
141			}
142		}
143	
144		if request.KeeplistRules != nil {
145			if !IsValidRegex(*request.KeeplistRules) {
146				return locale.NewLocalizedError("error.feed_invalid_keeplist_rule")
147			}
148		}
149	
150		if request.RewriteRules != nil {
151			if err := IsValidRewriteRules(*request.RewriteRules); err != nil {
152				return err
153			}
154		}
155	
156		if request.ScraperRules != nil {
157			if err := IsValidScraperRules(*request.ScraperRules); err != nil {
158				return err
159			}
160		}
161	
162		if request.UrlRewriteRules != nil {
