18	func TestParser(t *testing.T) {
19		translations, err := parseTranslationMessages([]byte(`{"k": "v"}`))
20		if err != nil {
21			t.Fatalf(`Unexpected parsing error: %v`, err)
22		}
23	
24		value, found := translations.singulars["k"]
25		if !found {
26			t.Fatalf(`The translation %v should contains the defined key`, translations.singulars)
