34	// TestGetTranslationDictConcurrency exercises the lazy population of the
35	// catalog from concurrent goroutines, as HTTP request handlers do. It must be
36	// run with the race detector enabled to catch unsynchronized catalog access.
37	func TestGetTranslationDictConcurrency(t *testing.T) {
38		defaultCatalog = make(catalog, len(AvailableLanguages))
39	
40		const iterations = 10
41	
42		var wg sync.WaitGroup
43		for i := 0; i < iterations; i++ {
44			for language := range AvailableLanguages {
45				wg.Add(1)
46				go func(language string) {
47					defer wg.Done()
48	
49					dict, err := getTranslationDict(language)
50					if err != nil {
51						t.Errorf(`Unable to get translation dictionary for language %q: %v`, language, err)
52						return
53					}
54					if len(dict.singulars) == 0 {
55						t.Errorf(`The translation dictionary for language %q should not be empty`, language)
56					}
57				}(language)
58			}
59		}
60		wg.Wait()
61	}
62	
63	func TestLoadCatalog(t *testing.T) {
64		for language := range AvailableLanguages {
65			_, err := loadTranslationFile(language)
66			if err != nil {
67				t.Fatal(err)
68			}
69		}
70	}
71	
72	func TestAllKeysHaveValue(t *testing.T) {
73		for language := range AvailableLanguages {
74			messages, err := loadTranslationFile(language)
75			if err != nil {
76				t.Fatalf(`Unable to load translation messages for language %q`, language)
77			}
78	
79			if len(messages.singulars) == 0 {
80				t.Fatalf(`The language %q doesn't have any messages for singulars`, language)
81			}
82	
83			if len(messages.plurals) == 0 {
84				t.Fatalf(`The language %q doesn't have any messages for plurals`, language)
85			}
86	
87			for k, v := range messages.singulars {
88				if len(v) == 0 {
89					t.Errorf(`The key %q for singulars for the language %q has an empty list as value`, k, language)
90				}
91			}
92			for k, v := range messages.plurals {
93				if len(v) == 0 {
94					t.Errorf(`The key %q for plurals for the language %q has an empty list as value`, k, language)
95				}
96			}
97		}
98	}
99	
100	func TestMissingTranslations(t *testing.T) {
101		refLang := "en_US"
102		references, err := loadTranslationFile(refLang)
103		if err != nil {
104			t.Fatal(`Unable to parse reference language`)
105		}
106	
107		for language := range AvailableLanguages {
108			if language == refLang {
109				continue
110			}
111	
112			messages, err := loadTranslationFile(language)
113			if err != nil {
114				t.Fatalf(`Parsing error for language %q`, language)
115			}
116	
117			for key := range references.singulars {
118				if _, found := messages.singulars[key]; !found {
119					t.Errorf(`Translation key %q not found in language %q singulars`, key, language)
120				}
121			}
122			for key := range references.plurals {
123				if _, found := messages.plurals[key]; !found {
124					t.Errorf(`Translation key %q not found in language %q plurals`, key, language)
125				}
126			}
127		}
128	}
129	
130	func TestTranslationFilePluralForms(t *testing.T) {
131		var numberOfPluralFormsPerLanguage = map[string]int{
132			"ar_SA":            6,
133			"de_DE":            2,
134			"el_EL":            2,
135			"en_US":            2,
136			"es_ES":            2,
137			"fi_FI":            2,
138			"fr_FR":            2,
139			"gl_ES":            2,
140			"hi_IN":            2,
141			"id_ID":            1,
142			"it_IT":            2,
143			"ja_JP":            1,
144			"ko_KR":            1,
145			"nan_Latn_pehoeji": 1,
146			"nl_NL":            2,
147			"pl_PL":            3,
148			"pt_BR":            2,
149			"ro_RO":            3,
150			"ru_RU":            3,
151			"tr_TR":            2,
152			"uk_UA":            3,
153			"vi_VN":            1,
154			"zh_CN":            1,
155			"zh_TW":            1,
156		}
157		for language := range AvailableLanguages {
158			messages, err := loadTranslationFile(language)
159			if err != nil {
160				t.Fatalf(`Unable to load translation messages for language %q`, language)
161			}
162	
163			for k, v := range messages.plurals {
164				if len(v) != numberOfPluralFormsPerLanguage[language] {
165					t.Errorf(`The key %q for the language %q does not have the expected number of plurals, got %d instead of %d`, k, language, len(v), numberOfPluralFormsPerLanguage[language])
166				}
167			}
168		}
